//[Example] When connect from master process to worker process  
// Master process
FJMPI_Mswk_connect(worker_port, …, &worker_comm);
MPI_Send(…, worker_comm, …);
FJMPI_Mswk_disconnect(&worker_comm);  
// Woker process
